using System;using System.Collections;using System.Collections.Generic;using System.Data;using System.Web;using System.Web.Services;using System.Web.UI;using WebPortal.App_Code.BLL;
namespace WebPortal.Admin{public partial class IDCardProcedure:Page{protected void Page_Load(object s,EventArgs e){}[WebMethod]public static IDCardData GetData(){var b=new bllMaster();return new IDCardData{New=P(b.GetEmployeeForIDCard()),InProcess=P(b.GetEmployeeForInProcessIDCard()),Issued=P(b.GetEmployeeForProvidedIDCard()),Dropout=P(b.GetDropOutEmployeeForIDCard()),Report=P(b.GetEmployeesIDCardDetailsForReport())};}[WebMethod]public static Result Save(List<string> codes,string status,string subStatus,string issuedDate,string remark){if(codes==null||codes.Count==0||String.IsNullOrWhiteSpace(status)||String.IsNullOrWhiteSpace(subStatus))return new Result(false,"Select employee, status and sub-status.");int n=0,u=Convert.ToInt32(HttpContext.Current.User.Identity.Name);foreach(var code in codes){var h=new Hashtable{{"Code",code},{"Status",status},{"SubStatus",subStatus},{"Remark",remark??""},{"RemarkBy",u},{"IssuedDate",String.IsNullOrWhiteSpace(issuedDate)?null:(object)issuedDate}};if(new bllMaster().InsertIDCardDetails(h)>0)n++;}return new Result(n==codes.Count,n+" employee record(s) updated.");}static IDCardTableData P(DataTable t){var x=new IDCardTableData();if(t==null)return x;foreach(DataColumn c in t.Columns)x.Columns.Add(c.ColumnName);foreach(DataRow r in t.Rows){var d=new Dictionary<string,object>();foreach(DataColumn c in t.Columns)d[c.ColumnName]=r[c]==DBNull.Value?"":r[c] is DateTime?((DateTime)r[c]).ToString("dd-MMM-yyyy"):r[c];x.Rows.Add(d);}return x;}}public class IDCardData{public IDCardTableData New{get;set;}public IDCardTableData InProcess{get;set;}public IDCardTableData Issued{get;set;}public IDCardTableData Dropout{get;set;}public IDCardTableData Report{get;set;}}public class IDCardTableData{public List<string> Columns{get;set;}=new List<string>();public List<Dictionary<string,object>> Rows{get;set;}=new List<Dictionary<string,object>>();}public class Result{public bool Success{get;set;}public string Message{get;set;}public Result(){}public Result(bool s,string m){Success=s;Message=m;}}}
